import {appStorage} from './storage.79382adbbf2a.js';
const $=s=>document.querySelector(s);
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>String(s??'').normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();
const KEY='boschetto-nutrition-v1';
const fields=['kcal','protein','carbs','fat'];
let records={},catalog=[],current=null,basis='100g';
try{records=JSON.parse(appStorage.getItem(KEY)||'{}')}catch{}
function defaults(i){return {basis:'100g',portion_label:'',portion_grams:null,values:{'100g':{kcal:i.kcal_100g??null,protein:i.protein_g_100g??null,carbs:i.carbs_g_100g??null,fat:i.fat_g_100g??null},portion:{kcal:null,protein:null,carbs:null,fat:null}}}}
function record(i){return records[i.ingredient_id]||defaults(i)}
function render(){const query=normalize($('#ingredient-search').value);const list=catalog.filter(i=>normalize(i.name_it+' '+i.name_nl).includes(query));$('#ingredient-count').textContent=`${list.length} ingredienti`;$('#ingredient-catalog').innerHTML=list.map(i=>{const r=record(i),v=r.values[r.basis];const complete=fields.every(f=>v[f]!==null&&v[f]!==undefined);return `<button type="button" class="catalog-row" data-ingredient="${escape(i.ingredient_id)}"><span><strong>${escape(i.name_it)}</strong><small>${escape(i.name_nl)}</small></span><span class="catalog-summary">${complete?escape(v.kcal)+' kcal · '+(r.basis==='100g'?'100 g':'porzione'):'Da completare'} <span aria-hidden="true">›</span></span></button>`}).join('')||'<p class="small">Nessun ingrediente trovato.</p>'}
function readValues(){const values={};for(const f of fields){const input=$('#nut-'+f);if(!input.checkValidity()){input.reportValidity();return null}values[f]=input.value===''?null:Number(input.value)}return values}
function fillValues(){const values=current.values[basis];for(const f of fields)$('#nut-'+f).value=values[f]??'';$('#portion-fields').hidden=basis!=='portion';$('#nutrition-basis-label').textContent=basis==='100g'?'Valori per 100 grammi':'Valori per una porzione'}
function openEditor(id){const item=catalog.find(i=>i.ingredient_id===id);current=JSON.parse(JSON.stringify(record(item)));current.ingredient_id=id;basis=current.basis;$('#nutrition-name').textContent=item.name_it;$('#nutrition-basis').value=basis;$('#portion-label').value=current.portion_label;$('#portion-grams').value=current.portion_grams??'';$('#nutrition-error').textContent='';$('#nutrition-list-view').hidden=true;$('#nutrition-edit-view').hidden=false;fillValues();$('#nutrition-basis').focus()}
$('#open-ingredients').onclick=async()=>{const dialog=$('#nutrition-dialog');$('#nutrition-list-view').hidden=false;$('#nutrition-edit-view').hidden=true;$('#nutrition-status').textContent='';dialog.showModal();try{const db=await appStorage.catalog();const byId=new Map(db.catalogo_ingredienti.map(i=>[i.ingredient_id,i]));let custom=[];try{custom=(()=>{const state=JSON.parse(appStorage.getItem('boschetto-v1')||'{}');return [...(state.customRecipes||[]),...Object.values(state.editedRecipes||{})]})()}catch{}for(const r of custom)for(const i of r.ingredients)if(!byId.has(i.ingredient_id))byId.set(i.ingredient_id,{ingredient_id:i.ingredient_id,name_it:i.ingredient_name,name_nl:i.name_nl||''});catalog=[...byId.values()].sort((a,b)=>a.name_it.localeCompare(b.name_it,'it'));$('#ingredient-search').value='';render();$('#ingredient-search').focus()}catch{$('#nutrition-status').textContent='Impossibile caricare il catalogo. Chiudi e riprova.'}};
$('#close-nutrition').onclick=()=>$('#nutrition-dialog').close();
$('#ingredient-search').oninput=render;
$('#ingredient-catalog').onclick=e=>{const button=e.target.closest('[data-ingredient]');if(button)openEditor(button.dataset.ingredient)};
$('#nutrition-basis').onchange=e=>{const values=readValues();if(!values){e.target.value=basis;return}current.values[basis]=values;basis=e.target.value;fillValues()};
$('#cancel-nutrition-edit').onclick=()=>{$('#nutrition-edit-view').hidden=true;$('#nutrition-list-view').hidden=false;$('#ingredient-search').focus()};
$('#nutrition-form').onsubmit=e=>{e.preventDefault();const values=readValues();if(!values||!e.target.reportValidity())return;current.values[basis]=values;current.basis=basis;current.portion_label=$('#portion-label').value.trim();current.portion_grams=$('#portion-grams').value===''?null:Number($('#portion-grams').value);const next={...records,[current.ingredient_id]:current};try{appStorage.setItem(KEY,JSON.stringify(next))}catch{$('#nutrition-error').textContent='Salvataggio non riuscito. Controlla lo spazio disponibile o le impostazioni del browser.';return}records=next;$('#nutrition-edit-view').hidden=true;$('#nutrition-list-view').hidden=false;$('#nutrition-status').textContent='Dati nutrizionali salvati. Controlla lo stato di sincronizzazione in alto.';render();$('#ingredient-search').focus()};
